import Foundation

enum BriefLocalization {
    static func text(en: String, ru: String) -> String {
        let code = preferredLanguageCode
        if code == "ru" {
            return ru
        }
        return translations[code]?[en] ?? en
    }

    private static var preferredLanguageCode: String {
        let candidates = [
            Bundle.main.preferredLocalizations.first,
            Locale.preferredLanguages.first,
            Locale.current.identifier,
        ]
        .compactMap { $0 }

        for candidate in candidates {
            let normalized = candidate.replacingOccurrences(of: "_", with: "-")
            if normalized.hasPrefix("ru") {
                return "ru"
            }
            if translations.keys.contains(normalized) {
                return normalized
            }
            guard let baseCode = normalized.split(separator: "-").first.map(String.init) else { continue }
            if baseCode == "ru" {
                return "ru"
            }
            if translations.keys.contains(baseCode) {
                return baseCode
            }
        }

        return "en"
    }

    private static let languageCodes = ["de", "es", "fr", "hi", "id", "it", "ja", "ko", "pt", "tr"]

    private static let translations: [String: [String: String]] = {
        rawTranslations.split(separator: "\n", omittingEmptySubsequences: true).reduce(into: [:]) { result, row in
            let columns = row.split(separator: "\t", omittingEmptySubsequences: false).map(String.init)
            guard columns.count == languageCodes.count + 1 else { return }
            let key = columns[0]
            for (index, code) in languageCodes.enumerated() {
                result[code, default: [:]][key] = columns[index + 1]
            }
        }
    }()

